/**
 * Generated by `pnpm theme:generate`. Do not edit.
 *
 * The baseline theme, as the Worker sees it: normalised name to source. The
 * keys are the complete set of templates the admin may edit -- an override
 * cannot introduce a name the theme does not ship, which is what makes the
 * whitelist check a memory lookup rather than a prefix test.
 */

export const BASELINE: Record<string, string> = {
  "layouts/base": "<!doctype html>\n<html lang=\"{{ site.language | default: 'en' }}\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    {% render 'snippets/seo-meta', seo: seo, page: page %}\n    <link rel=\"stylesheet\" href=\"{{ 'theme.css' | asset_url }}\">\n  </head>\n  <body>\n    {% render 'snippets/header', site: site %}\n    <main id=\"main\">\n      {% block %}{% endblock %}\n    </main>\n    {% render 'snippets/footer', site: site %}\n    {% render 'snippets/cookie-consent', site: site %}\n  </body>\n</html>\n",
  "snippets/cookie-consent": "{% if site.settings.cookie_notice %}\n  <div class=\"cookie-consent\" role=\"status\" hidden data-cookie-consent>\n    <p>{{ site.settings.cookie_notice }}</p>\n    <button type=\"button\" data-cookie-consent-accept>Got it</button>\n  </div>\n  <script src=\"{{ 'theme.js' | asset_url }}\" defer></script>\n{% endif %}\n",
  "snippets/footer": "<footer class=\"site-footer\">\n  {% if site.settings.footer %}<p>{{ site.settings.footer }}</p>{% endif %}\n  {% if site.settings.social_links.size > 0 %}\n    <ul class=\"social\">\n      {% for link in site.settings.social_links %}\n        <li><a href=\"{{ link.href }}\">{{ link.label }}</a></li>\n      {% endfor %}\n    </ul>\n  {% endif %}\n  {% if site.settings.filing_number %}<p class=\"filing\">{{ site.settings.filing_number }}</p>{% endif %}\n</footer>\n",
  "snippets/header": "<header class=\"site-header\">\n  <a class=\"brand\" href=\"{{ '/' | url }}\">\n    {% if site.logo_url %}<img src=\"{{ site.logo_url }}\" alt=\"{{ site.name }}\">{% else %}{{ site.name }}{% endif %}\n  </a>\n  <nav aria-label=\"Main\">\n    <ul>\n      {% for item in site.nav %}\n        <li><a href=\"{{ item.href | url }}\">{{ item.label }}</a></li>\n      {% endfor %}\n    </ul>\n  </nav>\n</header>\n",
  "snippets/pagination": "{% if page.pagination %}\n  <nav class=\"pagination\" aria-label=\"Pagination\">\n    {% if page.pagination.previous_url %}\n      <a rel=\"prev\" href=\"{{ page.pagination.previous_url | url }}\">Newer</a>\n    {% endif %}\n    <span>{{ page.pagination.page }} / {{ page.pagination.pages }}</span>\n    {% if page.pagination.next_url %}\n      <a rel=\"next\" href=\"{{ page.pagination.next_url | url }}\">Older</a>\n    {% endif %}\n  </nav>\n{% endif %}\n",
  "snippets/post-card": "{% comment %}\n  One row of the post list. `post` is what the caller passes: a summary, not the\n  whole document -- a list renders titles and summaries, and the bodies of ten\n  posts would be a page's context with ten posts' worth of JSON nothing reads.\n{% endcomment %}\n<article class=\"card\">\n  {% if post.cover_url %}\n    <a class=\"card-cover\" href=\"{{ post.url | url }}\">\n      <img src=\"{{ post.cover_url }}\" alt=\"{{ post.title }}\">\n    </a>\n  {% endif %}\n\n  <h2><a href=\"{{ post.url | url }}\">{{ post.title }}</a></h2>\n\n  <p class=\"meta\">\n    {% if post.published_at %}\n      <time datetime=\"{{ post.published_at }}\">{{ post.published_at | date: '%B %-d, %Y' }}</time>\n    {% endif %}\n    {% if post.category %}<span class=\"category\">{{ post.category }}</span>{% endif %}\n  </p>\n\n  {% if post.excerpt %}<p class=\"excerpt\">{{ post.excerpt }}</p>{% endif %}\n</article>\n",
  "snippets/product-card": "<article class=\"card\">\n  {% if product.cover_url %}<img src=\"{{ product.cover_url }}\" alt=\"{{ product.title }}\">{% endif %}\n  <h2><a href=\"{{ product.url | url }}\">{{ product.title }}</a></h2>\n  {% if product.price_label %}<p class=\"price\">{{ product.price_label }}</p>{% endif %}\n</article>\n",
  "snippets/seo-meta": "<title>{{ seo.title }}</title>\n{% if seo.description %}<meta name=\"description\" content=\"{{ seo.description }}\">{% endif %}\n{% if page.canonical %}<link rel=\"canonical\" href=\"{{ page.canonical }}\">{% endif %}\n{% if seo.og_image %}<meta property=\"og:image\" content=\"{{ seo.og_image }}\">{% endif %}\n{% if seo.json_ld %}<script type=\"application/ld+json\">{{ seo.json_ld | json }}</script>{% endif %}\n",
  "templates/404": "{% layout 'layouts/base' %}\n<article class=\"not-found\">\n  <h1>Page not found</h1>\n  <p>That address does not exist on this site. It may have been moved, or the link that brought you here may be wrong.</p>\n  <p><a href=\"{{ '/' | url }}\">Back to {{ site.name }}</a></p>\n</article>\n",
  "templates/home": "{% layout 'layouts/base' %}\n{% comment %} The home page: whichever page is flagged is_home, rendered as blocks. {% endcomment %}\n<article class=\"prose\">\n  <h1>{{ content.title }}</h1>\n  {{ content.blocks | render_blocks }}\n</article>\n",
  "templates/page": "{% layout 'layouts/base' %}\n<article class=\"prose\">\n  <h1>{{ content.title }}</h1>\n  {{ content.blocks | render_blocks }}\n</article>\n",
  "templates/post": "{% layout 'layouts/base' %}\n<article class=\"prose\">\n  <header class=\"post-header\">\n    <h1>{{ content.title }}</h1>\n    <p class=\"meta\">\n      {% if content.published_at %}\n        <time datetime=\"{{ content.published_at }}\">{{ content.published_at | date: '%B %-d, %Y' }}</time>\n      {% endif %}\n      {% if content.category %}<span class=\"category\">{{ content.category }}</span>{% endif %}\n    </p>\n  </header>\n\n  {% if content.cover_url %}\n    <img class=\"cover\" src=\"{{ content.cover_url }}\" alt=\"{{ content.title }}\">\n  {% endif %}\n\n  {{ content.blocks | render_blocks }}\n\n  {% if content.tags.size > 0 %}\n    <ul class=\"tags\" aria-label=\"Tags\">\n      {% for tag in content.tags %}<li>{{ tag }}</li>{% endfor %}\n    </ul>\n  {% endif %}\n</article>\n",
  "templates/posts": "{% layout 'layouts/base' %}\n<header class=\"list-header\">\n  <h1>{{ page.title | default: 'Posts' }}</h1>\n</header>\n\n<ul class=\"post-list\">\n  {% for post in content %}\n    <li>{% render 'snippets/post-card', post: post %}</li>\n  {% else %}\n    {% comment %}\n      `for ... else` rather than a length check: with an empty list there is\n      nothing to count, and this reads as what it is.\n    {% endcomment %}\n    <li class=\"empty\">Nothing has been published yet.</li>\n  {% endfor %}\n</ul>\n\n{% render 'snippets/pagination', page: page %}\n",
  "templates/product": "{% layout 'layouts/base' %}\n<article class=\"product\">\n  <h1>{{ content.title }}</h1>\n  {% if content.price_label %}<p class=\"price\">{{ content.price_label }}</p>{% endif %}\n  {% if content.gallery.size > 0 %}\n    <ul class=\"gallery\">\n      {% for image in content.gallery %}<li><img src=\"{{ image }}\" alt=\"{{ content.title }}\"></li>{% endfor %}\n    </ul>\n  {% endif %}\n  {{ content.blocks | render_blocks }}\n  {% if content.specs.size > 0 %}\n    <dl class=\"specs\">\n      {% for spec in content.specs %}<dt>{{ spec.label }}</dt><dd>{{ spec.value }}</dd>{% endfor %}\n    </dl>\n  {% endif %}\n  {% if content.cta_url %}\n    <a class=\"cta\" href=\"{{ content.cta_url }}\">{{ content.cta_label | default: 'Learn more' }}</a>\n  {% endif %}\n</article>\n",
  "templates/products": "{% layout 'layouts/base' %}\n<h1>{{ page.title | default: 'Products' }}</h1>\n<ul class=\"product-list\">\n  {% for product in content %}\n    <li>{% render 'snippets/product-card', product: product %}</li>\n  {% else %}\n    <li class=\"empty\">No products yet.</li>\n  {% endfor %}\n</ul>\n{% render 'snippets/pagination', page: page %}\n",
}

/** The names, in the order a browser should show them. */
export const BASELINE_NAMES: string[] = Object.keys(BASELINE)
